  function isWishesUnlockedFromResponse(inv, data) {
    if (typeof inv.wishes_locked === 'boolean') return !inv.wishes_locked;
    var hasWishes = Array.isArray(inv.wishes) || Array.isArray(data?.data?.wishes);
    if (hasWishes) return true;
    var wv = inv.wishes_visibility || inv.wishesVisibility;
    return String(wv || '').toLowerCase() !== 'password';
  }

  function isRsvpsUnlockedFromResponse(inv, data) {
    if (typeof inv.rsvps_locked === 'boolean') return !inv.rsvps_locked;
    if (typeof inv.rsvp_locked === 'boolean') return !inv.rsvp_locked;
    var hasRsvps = Array.isArray(inv.rsvps) || Array.isArray(data?.data?.rsvps);
    if (hasRsvps) return true;
    var rv = inv.rsvp_visibility || inv.rsvps_visibility || inv.rsvpVisibility || inv.rsvpsVisibility;
    return String(rv || '').toLowerCase() !== 'password';
  }

  async function verifyWishPassword(password, opts) {
    opts = opts || {};
    var errTarget = opts.errEl || $('chrome-wish-unlock-error');
    var btnTarget = opts.btn || $('chrome-wish-unlock-btn');
    const ctx = getInvitationContext();
    if (!ctx.slug) return false;
    if (btnTarget) { btnTarget.disabled = true; btnTarget.textContent = 'Đang mở...'; }
    if (errTarget) errTarget.style.display = 'none';
    try {
      const url = 'https://api.hiweb.vn/api/v1/wedding/invitation?slug=' + encodeURIComponent(ctx.slug) + '&passwordWishes=' + encodeURIComponent(password);
      const res = await fetch(url, { headers: { Accept: 'application/json' } });
      const data = await res.json().catch(() => ({}));
      const inv = data?.data?.invitation || data;
      if (res.ok && inv) {
        if (inv.wishes_locked === true || inv.wishesLocked === true) {
          if (errTarget) { errTarget.textContent = 'Mật khẩu không đúng, vui lòng thử lại.'; errTarget.style.display = 'block'; errTarget.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
          return false;
        }
        if (!window.invitationLockStatus) window.invitationLockStatus = {};
        window.invitationLockStatus.wishesPassword = password;
        window.invitationLockStatus.password_wishes = password;
        try { sessionStorage.setItem('invitation_' + ctx.slug + '_wishes', password); } catch (e) {}
        syncWishLockState();
        const wishData = (data?.data && Array.isArray(data.data.wishes)) ? data.data.wishes
          : (Array.isArray(inv.wishes) ? inv.wishes : null);
        if (wishData) {
          latestWishes = wishData;
          renderWishes(latestWishes);
          if (typeof renderWishListInModal === 'function') renderWishListInModal(latestWishes);
        } else if (typeof refreshWishesFromApi === 'function') {
          setTimeout(refreshWishesFromApi, 50);
        }
        try { window.dispatchEvent(new CustomEvent('INVITATION_UNLOCKED')); } catch (e) {}
        return true;
      }
      if (errTarget) { errTarget.textContent = 'Mật khẩu không đúng, vui lòng thử lại.'; errTarget.style.display = 'block'; errTarget.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
      return false;
    } catch (e) {
      if (errTarget) { errTarget.textContent = 'Lỗi kết nối. Vui lòng thử lại.'; errTarget.style.display = 'block'; errTarget.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
      return false;
    } finally {
      if (btnTarget) { btnTarget.disabled = false; btnTarget.textContent = 'Mở khoá'; }
    }
  }

