            var sub = wForm.querySelector('button[type="submit"]');
            if (sub) { sub.disabled = true; sub.textContent = 'Đang mở...'; }
            verifyWishPassword(pwd, { errEl: wErr, btn: sub }).then(function(ok) {
              if (sub) { sub.disabled = false; sub.textContent = 'Mở khoá'; }
              if (!ok && wErr && wErr.style.display === 'none') { wErr.textContent = 'Mật khẩu không đúng, vui lòng thử lại.'; wErr.style.display = 'block'; }
            });
